\emph{Truth of !!a{formula}~$!A$ at~$t$} in a~$\mModel M$:
  \begin{enumerate}
  \item\ollabel{defn:sub:mmodels-since} \indcase{!A}{\Since  !B
    !C}{$\mSat{M}{\indfrm}[t]$ iff $\mSat{M}{!B}[t']$ for some $t' \in
    T$ with $t' \prec t$, and for all $s$ with $t' \prec s \prec t$,
    $\mSat{M}{!C}[s]$}
   \item\ollabel{defn:sub:mmodels-until} \indcase{!A}{\Until !B
    !C}{$\mSat{M}{\indfrm}[t]$ iff $\mSat{M}{!B}[t']$ for some $t' \in
    T$ with $t \prec t'$, and for all $s$ with $t \prec s \prec t'$,
    $\mSat{M}{!C}[s]$}
  \end{enumerate}
